    let graph = read_graph("/home/user/graph_edges.csv");
    let distance = bfs(&graph, "NODE_42", "NODE_91");
    let mut file = File::create("/home/user/shortest_path_result.txt").unwrap();
    file.write_all(distance.to_string().as_bytes()).unwrap();
}

